# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ENDANGERED vs. EXTINCT SPECIES (PAST AND PRESENT)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Endangered Species (Present Simple)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Definition: In danger of becoming extinct</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Giant Pandas: Live in bamboo forests in China</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Polar Bears: Lose their Arctic ice habitats</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• Asian Elephants / Caretta Caretta sea turtles</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Amur Leopards / Mediterranean Monk Seals</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">They are still alive, so we must protect them!</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">2. Extinct Species (Past Simple)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Definition: No longer alive on Earth today</text>\n  <text x="375" y="120" font-size="11" fill="#334155">• Dinosaurs: Disappeared 65 million years ago</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Dodo Bird: Became extinct in 1681 (Mauritius)</text>\n  <text x="375" y="164" font-size="11" fill="#334155">• Tasmanian Tiger: Died out in 1936</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• Woolly Mammoth / Saber-toothed Tiger</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">They lived in the past and became extinct.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GIVING EXPLANATIONS AND REASONS (BECAUSE / FOR / SO)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Why Did Animals Become Endangered?</text>\n  <text x="40" y="100" font-size="11" fill="#334155">• Overhunting: People hunted them for fur, tusks, skin.</text>\n  <text x="40" y="124" font-size="11" fill="#334155">• Habitat Loss: Humans cut down trees (deforestation).</text>\n  <text x="40" y="148" font-size="11" fill="#334155">• Pollution: People polluted seas, rivers and air.</text>\n  <text x="40" y="172" font-size="11" fill="#334155">• Global Warming: Icebergs melted in the Arctic.</text>\n  <text x="40" y="196" font-size="11" fill="#334155">• Illegal Trade: People kept wild animals in cages.</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">because + full sentence (Subject + Verb)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Cause and Effect Connectors</text>\n  <text x="375" y="100" font-size="11" font-weight="bold" fill="#166534">1. BECAUSE (Çünkü — Sebep Cümlesi):</text>\n  <text x="375" y="120" font-size="10.5" fill="#334155">Dodos became extinct because people hunted them.</text>\n  <text x="375" y="146" font-size="11" font-weight="bold" fill="#166534">2. FOR THEIR ... (...-ları için — Amaç/Sebep):</text>\n  <text x="375" y="166" font-size="10.5" fill="#334155">People hunted elephants for their ivory tusks.</text>\n  <text x="375" y="192" font-size="11" font-weight="bold" fill="#166534">3. SO / THAT\'S WHY (Bu yüzden — Sonuç):</text>\n  <text x="375" y="212" font-size="10.5" fill="#334155">Dodos couldn\'t fly, so hunters caught them easily.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">WILDLIFE FACT FILE AND PROTECTION SUGGESTIONS (E7.4.W1)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Animal Fact File: GIANT PANDA</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Class / Kind: Mammal (black and white fur)</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Habitat: Bamboo forests in China</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Diet: Herbivore (eats bamboo leaves)</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• Weight and Height: Around 110 kg / 1.5 m</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Lifespan: About 20 years in the wild</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Status: Endangered (Habitat loss)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">How to Protect Wildlife (Should / Shouldn\'t)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• We should protect national parks and reserves.</text>\n  <text x="375" y="120" font-size="11" fill="#334155">• We should plant trees and keep seas clean.</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• We should educate people about wildlife.</text>\n  <text x="375" y="164" font-size="11" fill="#334155">• We shouldn\'t destroy forests or hunt animals.</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• We shouldn\'t buy fur coats or ivory products.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Save Natural Habitats, Save Wild Animals!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
